package com.farika.soundflow;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalUi168Test {
 public static class FakeMain extends MainActivity {static int cloudCalls;protected LocalAudioStore localAudioStore(){return new LocalAudio168Test.SyntheticStore(this);}protected ScApi createApi(){return new ScApi(this){public Page search(String q,String next){cloudCalls++;throw new AssertionError("Unexpected cloud search");}public Page likes(String user,String next){cloudCalls++;throw new AssertionError("Unexpected cloud likes");}public Page playlists(String user,boolean liked,String next){cloudCalls++;throw new AssertionError("Unexpected cloud playlists");}};}}
 Context c;LocalAudio168Test.SyntheticStore store;ActivityController<FakeMain> ctrl;FakeMain a;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();LocalAudio168Test.SyntheticStore.reset();store=new LocalAudio168Test.SyntheticStore(c);FakeMain.cloudCalls=0;PlaybackService.instance=null;}
 @After public void cleanup(){if(ctrl!=null)ctrl.destroy();PlaybackService.instance=null;ResidentChecks.resetForTest();}
 Object field(String n)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);return f.get(a);}void invoke(String n,Class<?>[] types,Object... args)throws Exception{Method m=MainActivity.class.getDeclaredMethod(n,types);m.setAccessible(true);m.invoke(a,args);}
 void waitDone()throws Exception{long until=System.currentTimeMillis()+6000;do{Shadows.shadowOf(Looper.getMainLooper()).idle();if(!(Boolean)field("busy")&&!(Boolean)field("localMutating"))return;Thread.sleep(10);}while(System.currentTimeMillis()<until);fail("Local operation timed out");}
 void open()throws Exception{Bundle b=new Bundle();b.putString("process",SoundFlowApplication.PROCESS);b.putString("page","own");ctrl=Robolectric.buildActivity(FakeMain.class).create(b);a=ctrl.get();waitDone();}
 List<Library.Track> tracks()throws Exception{return (List<Library.Track>)field("visible");}LocalAudioStore.Entry add(String n)throws Exception{return store.add(Uri.parse("content://synthetic.audio/"+n),LocalAudioStore.READ);}
 @Test public void ownIsBetweenSearchAndLibraryAndNeedsNoSoundcloudLogin()throws Exception{add("a");open();LinearLayout nav=(LinearLayout)field("nav");assertEquals(4,nav.getChildCount());String[] names={"Для вас","Поиск","Своё","Медиатека"};for(int i=0;i<4;i++)assertEquals(names[i],((TextView)((ViewGroup)nav.getChildAt(i)).getChildAt(1)).getText().toString());assertEquals(1,tracks().size());assertEquals(View.GONE,((View)field("more")).getVisibility());assertEquals(0,FakeMain.cloudCalls);}
 @Test public void pickerUsesPersistedReferencesNotContentCopy()throws Exception{open();invoke("pickLocalAudio",new Class<?>[]{});Intent i=Shadows.shadowOf(a).getNextStartedActivityForResult().intent;assertEquals(Intent.ACTION_OPEN_DOCUMENT,i.getAction());assertEquals("audio/*",i.getType());assertTrue(i.hasCategory(Intent.CATEGORY_OPENABLE));assertTrue(i.getBooleanExtra(Intent.EXTRA_ALLOW_MULTIPLE,false));assertTrue(i.getBooleanExtra(Intent.EXTRA_LOCAL_ONLY,false));assertTrue((i.getFlags()&Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)!=0);}
 @Test public void multiSelectionDeduplicatesAndImportsMetadata()throws Exception{open();Uri one=Uri.parse("content://synthetic.audio/a"),two=Uri.parse("content://synthetic.audio/b");ClipData clip=ClipData.newRawUri("Audio",one);clip.addItem(new ClipData.Item(two));Intent result=new Intent().setData(one).addFlags(LocalAudioStore.READ);result.setClipData(clip);a.onActivityResult(81,Activity.RESULT_OK,result);waitDone();assertEquals(2,tracks().size());assertEquals(2,store.list(LocalAudioStore.Sort.NEWEST).size());assertEquals(0,c.getFilesDir().list().length);}
 @Test public void menuOffersTwoDistinctConfirmedRemovalActions()throws Exception{LocalAudioStore.Entry e=add("a");open();invoke("localAudioMenu",new Class<?>[]{Library.Track.class},e.track());AlertDialog menu=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertEquals("Убрать только из приложения",menu.getListView().getAdapter().getItem(0));assertEquals("Удалить вместе с файлом",menu.getListView().getAdapter().getItem(1));menu.getListView().performItemClick(null,1,1);AlertDialog confirm=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotSame(menu,confirm);confirm.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();assertNotNull(store.get(e.uri()));assertEquals(0,LocalAudio168Test.SyntheticStore.deletes);}
 @Test public void appOnlyRemovalKeepsSourceAndRefreshesList()throws Exception{LocalAudioStore.Entry e=add("a");open();invoke("removeLocalAudio",new Class<?>[]{String.class,boolean.class},e.uri(),false);waitDone();assertNull(store.get(e.uri()));assertEquals(0,tracks().size());assertEquals(0,LocalAudio168Test.SyntheticStore.deletes);}
 @Test public void refreshPrunesMissingButRetainsUnavailable()throws Exception{LocalAudioStore.Entry missing=add("a"),temporary=add("b");store.position(missing.uri(),4000,180000);LocalAudio168Test.SyntheticStore.access.put(missing.document,LocalAudioStore.Access.MISSING);LocalAudio168Test.SyntheticStore.access.put(temporary.document,LocalAudioStore.Access.UNAVAILABLE);open();assertEquals(1,tracks().size());assertEquals(temporary.uri(),tracks().get(0).uri);assertNull(store.get(missing.uri()));assertNotNull(store.get(temporary.uri()));}
 @Test public void sortChoicePersistsAndReordersList()throws Exception{LocalAudioStore.Entry first=add("Яблоко"),second=add("Абрикос");open();assertEquals(second.uri(),tracks().get(0).uri);invoke("sortLocalAudio",new Class<?>[]{});AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();dialog.getListView().performItemClick(null,1,1);waitDone();assertEquals(first.uri(),tracks().get(0).uri);assertEquals("OLDEST",c.getSharedPreferences("own_audio_ui",0).getString("sort",""));}
}
